public class ExampleClass :
AssetPostprocessor
{
// Increment the version number, when the AssetPostprocessors code/behavior is changed
static readonly uint k_Version = 0;
public override uint GetVersion() { return k_Version; }
void OnPostprocessGameObjectWithUserProperties(
GameObject
go,
string[] propNames,
System.Object[] values)
{
for (int i = 0; i < propNames.Length; i++)
{
string propName = propNames[i];
System.Object value = (System.Object)values[i];
Debug.Log
("Propname: " + propName + " value: " + values[i]);
if (value.GetType().ToString() == "System.Int32")
{
int myInt = (int)value;
// do something useful
}
// etc...
}
}
}
